<?php require __DIR__.'/bootstrap.php';$u=require_admin();$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'&&$id){$msg=trim($_POST['message']??'');if($msg){$pdo->prepare('INSERT INTO support_replies(ticket_id,author_id,message) VALUES(?,?,?)')->execute([$id,$u['id'],$msg]);$pdo->prepare("UPDATE support_tickets SET status='in_progress' WHERE id=?")->execute([$id]);}header('Location: admin_tickets.php?id='.$id);exit;}
if(isset($_GET['close'])){$pdo->prepare("UPDATE support_tickets SET status='closed' WHERE id=?")->execute([(int)$_GET['close']]);header('Location: admin_tickets.php');exit;}$tickets=$pdo->query('SELECT t.*,u.name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY FIELD(t.status,"open","in_progress","closed"),t.id DESC')->fetchAll();$ticket=null;$replies=[];if($id){$q=$pdo->prepare('SELECT t.*,u.name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);$ticket=$q->fetch();$r=$pdo->prepare('SELECT r.*,u.name FROM support_replies r JOIN users u ON u.id=r.author_id WHERE ticket_id=? ORDER BY r.id');$r->execute([$id]);$replies=$r->fetchAll();}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tickets — Administração</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="admin_tickets.php">♧ Suporte</a><a href="video_novo.php">▻ Vídeos Ultimate</a><a class="exit" href="logout.php">Sair</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Tickets de suporte</h1><span>Atenda seus assinantes por aqui.</span></div></header><div class="ticket-admin-grid"><section class="panel ticket-list"><?php foreach($tickets as $t):?><a class="ticket-line <?=($id===$t['id'])?'selected':''?>" href="admin_tickets.php?id=<?=$t['id']?>"><b>#<?=$t['id']?> · <?=e($t['subject'])?></b><small><?=e($t['name'])?> · <?=e($t['status'])?></small></a><?php endforeach;if(!$tickets):?><p class="muted">Nenhum ticket recebido.</p><?php endif?></section><section class="panel"><?php if($ticket):?><div class="ticket-head"><h2><?=e($ticket['subject'])?></h2><a class="outline" href="admin_tickets.php?close=<?=$ticket['id']?>">Encerrar</a></div><p class="muted">Cliente: <?=e($ticket['name'])?> · <?=e($ticket['email'])?></p><article class="message clientmsg"><?=nl2br(e($ticket['message']))?></article><?php foreach($replies as $reply):?><article class="message adminmsg"><small><?=e($reply['name'])?> · <?=date('d/m H:i',strtotime($reply['created_at']))?></small><?=nl2br(e($reply['message']))?></article><?php endforeach?><form method="post"><label>Responder ao cliente<textarea required name="message" placeholder="Escreva uma resposta clara para o assinante"></textarea></label><button class="redbtn">Enviar resposta →</button></form><?php else:?><p class="muted">Selecione um ticket ao lado para responder.</p><?php endif?></section></div></main></body></html>
